import 'package:flutter/material.dart';import 'package:flutter_riverpod/flutter_riverpod.dart';import 'package:go_router/go_router.dart';import 'request_providers.dart';class MyRequestsScreen extends ConsumerWidget{const MyRequestsScreen({super.key});@override Widget build(BuildContext c,WidgetRef r){final a=r.watch(myRequestsProvider);return Scaffold(appBar:AppBar(title:const Text('My requests'),actions:[IconButton(onPressed:()=>c.push('/requests/create'),icon:const Icon(Icons.add))]),body:a.when(data:(xs)=>xs.isEmpty?const Center(child:Text('No requests yet')):ListView.builder(itemCount:xs.length,itemBuilder:(_,i)=>ListTile(title:Text(xs[i].message,maxLines:1,overflow:TextOverflow.ellipsis),subtitle:Text(xs[i].createdAt?.toLocal().toString().split('.').first??''),trailing:Chip(label:Text(xs[i].status)),onTap:()=>c.push('/requests/${xs[i].id}'))),loading:()=>const Center(child:CircularProgressIndicator()),error:(e,_)=>Center(child:Text('Unable to load requests: $e'))));}}
